describe('Login to Secure Area', () => {
  beforeEach(() => {
    cy.visit('/login');
  });

  it('should successfully log in and navigate to secure area with flash success message', () => {
    // Intercept the login API call
    cy.intercept('POST', '/api/auth/login').as('loginRequest');

    // Fill in the login form
    cy.get('[name="username"]').type('tomsmith');
    cy.get('[name="password"]').type('SuperSecretPassword!');

    // Click the login button
    cy.get('[type="submit"]').click();

    // Wait for the login API response
    cy.wait('@loginRequest');

    // Verify successful navigation
    cy.url().should('include', '/secure');

    // Verify flash success message is displayed
    cy.get('[data-testid="flash-messages"]').should('be.visible');
    cy.get('[data-testid="flash-messages"]').should('contain', 'You logged into a secure area!');

    // Verify user is redirected to secure content
    cy.get('[data-testid="content"]').should('be.visible');

    // Verify login form is cleared
    cy.get('[name="username"]').should('have.value', '');
    cy.get('[name="password"]').should('have.value', '');
  });

  it('should handle login failure and display error message', () => {
    // Intercept the login API call with a failed response
    cy.intercept('POST', '/api/auth/login', {
      statusCode: 401,
      body: { error: 'Invalid credentials' }
    }).as('loginRequest');

    // Fill in the login form with incorrect credentials
    cy.get('[name="username"]').type('invaliduser');
    cy.get('[name="password"]').type('WrongPassword');

    // Click the login button
    cy.get('[type="submit"]').click();

    // Wait for the failed login API response
    cy.wait('@loginRequest');

    // Verify error message is displayed
    cy.get('[data-testid="flash-messages"]').should('be.visible');
    cy.get('[data-testid="flash-messages"]').should('contain', 'Login failed');

    // Verify user is not redirected to secure content
    cy.get('[data-testid="content"]').should('not.exist');

    // Verify error message contains specific text
    cy.get('[data-testid="flash-messages"]').should('contain', 'Invalid credentials');
  });
});
